import React, { useState } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import './Tabs.css';

const Tabs = () => {
  const [activeTab, setActiveTab] = useState(0);

  const tabs = [
    { title: 'Add Tips', icon: '', component: Tips },
    { title: 'Manage Employees', icon: '', component: Employees },
    { title: 'View Summary', icon: '', component: Summary },
  ];

  return (
    <div className="tabs">
      <ul>
        {tabs.map((tab, index) => (
          <li key={index} title={tab.title}>
            <button onClick={() => setActiveTab(index)} role="button">
              <svg viewBox="0 0 24 24">
                <path d={tab.icon} />
              </svg>
              <br />
              <span>{tab.title}</span>
            </button>
          </li>
        ))}
      </ul>

      {/* <div className="slider">
        <div
          className="indicator"
          style={{ transform: `translateX(${activeTab * 100}%)` }}
        ></div>
      </div> */}
      <div className="slider">
        <div
          className="indicator"
          style={{
            transform: `translateX(${activeTab * 100}%)`,
            width: `${100 / tabs.length}%`
          }}
        ></div>
      </div>

      <div className="content">
        {tabs.map((tab, index) => (
          <section key={index} style={{ display: index === activeTab ? 'block' : 'none' }}>
            <h2>{tab.title}</h2>
            {tab.component ? <tab.component /> : <p>{tab.content}</p>}
          </section>
        ))}
      </div>
    </div>
  );
};

export default Tabs;
